-- S:HOMEs demo v1.0: reference PostgreSQL DDL.
-- Translate into Prisma migrations; do not run this and duplicate CREATE migrations.
-- UUIDs are generated by application/seed. Business transitions live in services.
BEGIN;
CREATE TYPE user_role AS ENUM ('owner','admin');
CREATE TYPE moderation_status AS ENUM ('draft','pending','approved','rejected','hidden');
CREATE TYPE availability_status AS ENUM ('available','rented');
CREATE TYPE viewing_status AS ENUM ('requested','confirmed','cancelled');

CREATE TABLE users (
 id uuid PRIMARY KEY, email varchar(254) NOT NULL UNIQUE,
 password_hash text NOT NULL, role user_role NOT NULL,
 display_name varchar(100) NOT NULL CHECK(length(trim(display_name)) BETWEEN 2 AND 100),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK (email=lower(trim(email)))
);
CREATE TABLE owner_profiles (
 user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 public_phone varchar(20),
 bio varchar(1000), version integer NOT NULL DEFAULT 1 CHECK(version>=1),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (
 id uuid PRIMARY KEY, token_hash char(64) NOT NULL UNIQUE,
 user_id uuid REFERENCES users(id) ON DELETE CASCADE,
 csrf_hash char(64) NOT NULL, expires_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE areas (
 code varchar(50) PRIMARY KEY, name varchar(150) NOT NULL,
 active boolean NOT NULL DEFAULT true
);
CREATE TABLE amenities (
 code varchar(50) PRIMARY KEY, label varchar(100) NOT NULL
);
CREATE TABLE places (
 id uuid PRIMARY KEY, name varchar(200) NOT NULL, search_text text NOT NULL,
 area_code varchar(50) NOT NULL REFERENCES areas(code),
 latitude numeric(9,6) NOT NULL CHECK(latitude BETWEEN -90 AND 90),
 longitude numeric(9,6) NOT NULL CHECK(longitude BETWEEN -180 AND 180),
 is_demo boolean NOT NULL DEFAULT true
);
CREATE TABLE listings (
 id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id),
 moderation_status moderation_status NOT NULL DEFAULT 'draft',
 availability availability_status NOT NULL DEFAULT 'available',
 version integer NOT NULL DEFAULT 1 CHECK(version>=1),
 title varchar(120), description text, search_text text NOT NULL DEFAULT '',
 area_code varchar(50) REFERENCES areas(code), address varchar(300),
 latitude numeric(9,6) CHECK(latitude BETWEEN -90 AND 90),
 longitude numeric(9,6) CHECK(longitude BETWEEN -180 AND 180),
 area_m2 numeric(8,2) CHECK(area_m2>0 AND area_m2<=1000),
 max_occupants integer CHECK(max_occupants BETWEEN 1 AND 10),
 rent_vnd bigint CHECK(rent_vnd BETWEEN 1 AND 100000000),
 deposit_vnd bigint CHECK(deposit_vnd BETWEEN 0 AND 1000000000),
 electricity_vnd_per_kwh bigint CHECK(electricity_vnd_per_kwh BETWEEN 0 AND 100000),
 water_vnd_per_person bigint CHECK(water_vnd_per_person BETWEEN 0 AND 10000000),
 internet_vnd bigint CHECK(internet_vnd BETWEEN 0 AND 10000000),
 parking_vnd_per_vehicle bigint CHECK(parking_vnd_per_vehicle BETWEEN 0 AND 10000000),
 service_vnd bigint CHECK(service_vnd BETWEEN 0 AND 10000000),
 other_vnd bigint CHECK(other_vnd BETWEEN 0 AND 10000000),
 amenities jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(amenities)='object'),
 house_rules varchar(2000), moderation_reason varchar(1000),
 availability_updated_at timestamptz, submitted_at timestamptz, approved_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK ((latitude IS NULL)=(longitude IS NULL)),
 CHECK (moderation_status NOT IN ('rejected','hidden') OR
        (moderation_reason IS NOT NULL AND length(trim(moderation_reason))>=5)),
 CHECK (moderation_status NOT IN ('pending','approved') OR
        (title IS NOT NULL AND description IS NOT NULL AND area_code IS NOT NULL AND
         address IS NOT NULL AND latitude IS NOT NULL AND longitude IS NOT NULL AND
         area_m2 IS NOT NULL AND max_occupants IS NOT NULL AND rent_vnd IS NOT NULL))
);
CREATE INDEX listings_owner_idx ON listings(owner_id,updated_at DESC);
CREATE INDEX listings_queue_idx ON listings(moderation_status,submitted_at);
CREATE INDEX listings_public_idx ON listings(area_code,rent_vnd,updated_at DESC)
 WHERE moderation_status='approved' AND availability='available';

CREATE TABLE media_assets (
 id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id),
 storage_key text NOT NULL UNIQUE, mime varchar(50) NOT NULL DEFAULT 'image/webp',
 size_bytes bigint NOT NULL CHECK(size_bytes>0), width integer NOT NULL CHECK(width>0),
 height integer NOT NULL CHECK(height>0),
 status varchar(20) NOT NULL DEFAULT 'ready' CHECK(status='ready'),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE listing_images (
 listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
 asset_id uuid NOT NULL UNIQUE REFERENCES media_assets(id),
 sort_order integer NOT NULL CHECK(sort_order BETWEEN 0 AND 9),
 PRIMARY KEY(listing_id,asset_id), UNIQUE(listing_id,sort_order)
);
CREATE TABLE moderation_events (
 id uuid PRIMARY KEY, listing_id uuid NOT NULL REFERENCES listings(id),
 actor_id uuid NOT NULL REFERENCES users(id),
 action varchar(40) NOT NULL, from_status moderation_status, to_status moderation_status,
 reason varchar(1000), listing_version integer NOT NULL,
 details jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX moderation_events_listing_idx ON moderation_events(listing_id,created_at);
CREATE TABLE viewing_requests (
 id uuid PRIMARY KEY, receipt_code varchar(30) NOT NULL UNIQUE,
 listing_id uuid NOT NULL REFERENCES listings(id),
 session_id uuid REFERENCES sessions(id) ON DELETE SET NULL,
 guest_name varchar(100), guest_phone varchar(20), note varchar(1000),
 consent_contact boolean NOT NULL CHECK(consent_contact=true),
 preferred_at timestamptz NOT NULL, status viewing_status NOT NULL DEFAULT 'requested',
 cancellation_reason varchar(1000), version integer NOT NULL DEFAULT 1 CHECK(version>=1),
 anonymized_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(status!='cancelled' OR (cancellation_reason IS NOT NULL AND length(trim(cancellation_reason))>=5)),
 CHECK(anonymized_at IS NOT NULL OR (guest_name IS NOT NULL AND guest_phone IS NOT NULL))
);
CREATE INDEX viewing_listing_time_idx ON viewing_requests(listing_id,preferred_at);
CREATE INDEX viewing_status_time_idx ON viewing_requests(status,preferred_at);
CREATE UNIQUE INDEX viewing_active_duplicate_uq ON viewing_requests(listing_id,guest_phone,preferred_at)
 WHERE status IN ('requested','confirmed');
CREATE TABLE idempotency_keys (
 session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
 route varchar(100) NOT NULL, key uuid NOT NULL, request_hash char(64) NOT NULL,
 response_json jsonb NOT NULL, expires_at timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(session_id,route,key)
);
CREATE INDEX idempotency_expiry_idx ON idempotency_keys(expires_at);
CREATE TABLE ai_conversations (
 id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
 filters_json jsonb NOT NULL DEFAULT '{}'::jsonb,
 pending_proposals_json jsonb NOT NULL DEFAULT '[]'::jsonb,
 version integer NOT NULL DEFAULT 1 CHECK(version>=1),
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days')
);
CREATE TABLE ai_messages (
 id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES ai_conversations(id) ON DELETE CASCADE,
 turn_id uuid NOT NULL, role varchar(20) NOT NULL CHECK(role IN ('user','assistant')),
 text text NOT NULL, request_hash char(64), response_json jsonb,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(conversation_id,turn_id,role)
);
CREATE TABLE travel_estimates (
 listing_id uuid NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
 place_id uuid NOT NULL REFERENCES places(id) ON DELETE CASCADE,
 mode varchar(20) NOT NULL CHECK(mode='driving'),
 source varchar(20) NOT NULL CHECK(source IN ('fixture','osrm')),
 duration_seconds integer NOT NULL CHECK(duration_seconds>=0),
 distance_meters integer NOT NULL CHECK(distance_meters>=0),
 calculated_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz,
 PRIMARY KEY(listing_id,place_id,mode,source)
);
COMMIT;
